create table if not exists public.scraper_jobs (id uuid primary key, requested_category text not null, city text not null, state text not null, target integer not null check (target > 0), worker_count integer not null check (worker_count between 1 and 2), reviews_mode text not null default 'summary', status text not null default 'queued', stop_reason text, dry_run boolean not null default true, current_count integer not null default 0, qualified_count integer not null default 0, dedupe_count integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.scraper_job_shards (id bigint generated by default as identity primary key, job_id uuid not null references public.scraper_jobs(id) on delete cascade, shard_id text not null unique, worker_id text not null, status text not null default 'queued', provider_job_id text, query_set jsonb not null default '[]'::jsonb, started_at timestamptz, completed_at timestamptz, stop_reason text, qualified_count integer not null default 0, unique(job_id, worker_id));
create table if not exists public.scraper_job_events (id bigint generated by default as identity primary key, job_id uuid not null references public.scraper_jobs(id) on delete cascade, shard_id text, event_type text not null, place_identity text, payload jsonb not null default '{}'::jsonb, occurred_at timestamptz not null default now());
create index if not exists scraper_job_events_job_idx on public.scraper_job_events(job_id, occurred_at);
create index if not exists scraper_job_shards_job_idx on public.scraper_job_shards(job_id);

alter table public.scraper_jobs enable row level security;
alter table public.scraper_job_shards enable row level security;
alter table public.scraper_job_events enable row level security;
